import { type ItemCondition, type ItemRecord, matchItemCondition } from "@poe-tools/item-query";
import { z } from "zod";
import data from "../data/market-bases-poe1.json" with { type: "json" };

const bandSchema = z.strictObject({ min: z.number().int(), max: z.number().int() });

/** The equipment listed as crafting base markets, generated by `generate-market-cohorts.ts`. */
export const marketBaseListSchema = z.strictObject({
    bases: z.array(
        z.strictObject({
            baseType: z.string().min(1),
            category: z.string().min(1),
            itemClass: z.string().min(1),
            attributes: z.array(z.enum(["str", "dex", "int"])),
            level: z.number().int().nullable(),
            bands: z.array(bandSchema),
            /** Six sockets are reachable, so markets split by 1–5 and 6 links. */
            links: z.boolean(),
            /** Armour also splits item level 86+ by 25–29% and 30%+ quality. */
            quality: z.boolean(),
        }),
    ),
    clusters: z.array(
        z.strictObject({
            baseType: z.string().min(1),
            category: z.string().min(1),
            minPassives: z.number().int(),
            maxPassives: z.number().int(),
            bands: z.array(bandSchema),
            skills: z.array(
                z.strictObject({
                    id: z.string().min(1),
                    /** The first `Added Small Passive Skills grant:` enchantment line. */
                    line: z.string().min(1),
                    label: z.string().min(1),
                }),
            ),
        }),
    ),
});
export type MarketBaseList = z.infer<typeof marketBaseListSchema>;
export type MarketBaseEntry = MarketBaseList["bases"][number];
type MarketClusterEntry = MarketBaseList["clusters"][number];
type Band = z.infer<typeof bandSchema>;

const list = marketBaseListSchema.parse(data);
const equipment = new Map(list.bases.map((entry) => [entry.baseType, entry]));
const clusters = new Map(list.clusters.map((entry) => [entry.baseType, entry]));

export const MARKET_BASE_QUALITY_LEVEL = 86;
export const MARKET_BASE_QUALITIES = [25, 30] as const;
type MarketBaseQuality = (typeof MARKET_BASE_QUALITIES)[number];
type MarketBaseLinks = "1-5" | "6";

const QUALITY_BAND = { min: MARKET_BASE_QUALITY_LEVEL, max: 100 };

/** The listed base's category and its fields, for a base type with a crafting base market. */
export function marketBaseEntry(baseType: string): MarketBaseEntry | undefined {
    return equipment.get(baseType);
}

/** The category a crafting base market of this base type lists under. */
export function marketBaseMarketCategory(baseType: string) {
    return equipment.get(baseType)?.category ?? clusters.get(baseType)?.category;
}

/** Listed base types, with their item class ("Large Cluster Jewel" for a cluster's size). */
export function marketBaseTypes() {
    return [
        ...list.bases,
        ...list.clusters.map((entry) => ({
            ...entry,
            itemClass: entry.baseType,
            attributes: [] as MarketBaseEntry["attributes"],
        })),
    ];
}

function bandLabel({ min, max }: Band) {
    if (min === max) return `ilvl ${min}`;
    return max === 100 ? `ilvl ${min}+` : `ilvl ${min}–${max}`;
}

/** A crafting base market's `signatureValue`, e.g. `ilvl 86+ · 6 links · Quality 30%+`. */
export function marketBaseValue(
    band: Band,
    links?: MarketBaseLinks | null,
    quality?: MarketBaseQuality | null,
) {
    return [
        bandLabel(band),
        ...(links ? [`${links === "6" ? "6" : "1–5"} links`] : []),
        ...(quality ? [quality === 30 ? "Quality 30%+" : "Quality 25–29%"] : []),
    ].join(" · ");
}

/** A Cluster Jewel market's `signatureValue`. */
export function marketClusterValue(skill: string, passives: number, band: Band) {
    return `${skill} · ${passives} passives · ${bandLabel(band)}`;
}

/** Equipment and Cluster Jewel filters narrow base markets by level, links and quality. */
type MarketBaseVariantFilters = {
    category: string;
    ilvl: string;
    baseLinks: string;
    quality: string;
};

function bandIncludes(band: Band, level: string) {
    return !level || (band.min <= Number(level) && Number(level) <= band.max);
}

function equipmentValues(entry: MarketBaseEntry, filters: MarketBaseVariantFilters) {
    const links: (MarketBaseLinks | null)[] = entry.links ? ["1-5", "6"] : [null];
    const passing = links.filter((option) => !filters.baseLinks || option === filters.baseLinks);
    return passing.flatMap((option) => [
        ...(filters.quality
            ? []
            : entry.bands
                  .filter((band) => bandIncludes(band, filters.ilvl))
                  .map((band) => marketBaseValue(band, option))),
        ...(entry.quality && bandIncludes(QUALITY_BAND, filters.ilvl)
            ? MARKET_BASE_QUALITIES.filter(
                  (quality) => !filters.quality || quality >= Number(filters.quality),
              ).map((quality) => marketBaseValue(QUALITY_BAND, option, quality))
            : []),
    ]);
}

function clusterValues(entry: MarketClusterEntry, filters: MarketBaseVariantFilters) {
    if (filters.baseLinks || filters.quality) return [];
    const passives = Array.from(
        { length: entry.maxPassives - entry.minPassives + 1 },
        (_, index) => entry.minPassives + index,
    );
    return entry.bands
        .filter((band) => bandIncludes(band, filters.ilvl))
        .flatMap((band) =>
            entry.skills.flatMap((skill) =>
                passives.map((count) => marketClusterValue(skill.label, count, band)),
            ),
        );
}

/**
 * Every `signatureValue` of a category's base markets passing item level, link and quality filters,
 * or undefined when none is set. A level matches the band that includes it; a quality its band and
 * better.
 */
export function marketBaseVariantValues(filters: MarketBaseVariantFilters) {
    if (!filters.ilvl && !filters.baseLinks && !filters.quality) return undefined;
    return [
        ...new Set([
            ...list.bases
                .filter((entry) => entry.category === filters.category)
                .flatMap((entry) => equipmentValues(entry, filters)),
            ...list.clusters
                .filter((entry) => entry.category === filters.category)
                .flatMap((entry) => clusterValues(entry, filters)),
        ]),
    ];
}

const CLEAN_ITEM: ItemCondition[] = [
    { kind: "rarity", values: ["Normal", "Magic", "Rare"] },
    ...(
        ["corrupted", "mirrored", "fractured", "synthesised", "influenced", "intangible"] as const
    ).map((field): ItemCondition => ({ kind: "flag", field, value: false })),
];

function holds(record: ItemRecord, condition: ItemCondition) {
    return matchItemCondition(record, condition) === "match";
}

function equipmentValue(entry: MarketBaseEntry, record: ItemRecord) {
    const level = record.item.ilvl ?? record.item.itemLevel;
    if (level === undefined) return null;
    const links = entry.links
        ? holds(record, { kind: "range", field: "links", value: { min: 6 } })
            ? "6"
            : "1-5"
        : null;
    if (entry.quality && level >= MARKET_BASE_QUALITY_LEVEL) {
        const quality = MARKET_BASE_QUALITIES.findLast((min) =>
            holds(record, { kind: "range", field: "quality", value: { min } }),
        );
        if (quality) return marketBaseValue(QUALITY_BAND, links, quality);
    }
    const band = entry.bands.find(({ min, max }) => min <= level && level <= max);
    return band ? marketBaseValue(band, links) : null;
}

function clusterValue(entry: MarketClusterEntry, record: ItemRecord) {
    const level = record.item.ilvl ?? record.item.itemLevel;
    const band = entry.bands.find(
        ({ min, max }) => level !== undefined && min <= level && level <= max,
    );
    const enchant = (line: string) => holds(record, { kind: "enchant", values: [line] });
    const skill = entry.skills.find(({ line }) =>
        enchant(`Added Small Passive Skills grant: ${line}`),
    );
    if (!band || !skill) return null;
    for (let count = entry.minPassives; count <= entry.maxPassives; count++)
        if (enchant(`Adds ${count} Passive Skills`))
            return marketClusterValue(skill.label, count, band);
    return null;
}

/**
 * A listed base's market for a clean item: normal, magic or rare, and not corrupted, mirrored,
 * fractured, synthesised, influenced or intangible. Null for any other item.
 */
export function marketBaseItemValue(record: ItemRecord) {
    const { baseType } = record.item;
    const entry = equipment.get(baseType);
    const cluster = clusters.get(baseType);
    if (!entry && !cluster) return null;
    if (!CLEAN_ITEM.every((condition) => holds(record, condition))) return null;
    return entry ? equipmentValue(entry, record) : clusterValue(cluster!, record);
}

/** Whether a base type is listed, before reading the item further. */
export function isMarketBaseType(baseType: string) {
    return equipment.has(baseType) || clusters.has(baseType);
}

const slug = (name: string) =>
    name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");

/**
 * The base market of an old crafting base page's cohort ID, or undefined when that base is no
 * longer listed: `base:<base>:<min>-<max>:<links>[:q<quality>]`, or for a Cluster Jewel
 * `base:<size>-cluster-jewel:<skill>:<passives>-passives:<min>-<max>`.
 */
export function marketBaseFromCohortId(id: string) {
    const [, name, ...parts] = id.split(":");
    const cluster = list.clusters.find((entry) => slug(entry.baseType) === name);
    if (cluster) {
        const [skillId, passives, band] = parts;
        const skill = cluster.skills.find((entry) => entry.id === skillId);
        const [min, max] = (band ?? "").split("-").map(Number);
        if (!skill || !min || !max) return undefined;
        return {
            baseType: cluster.baseType,
            category: cluster.category,
            value: marketClusterValue(skill.label, Number.parseInt(passives ?? "", 10), {
                min,
                max,
            }),
        };
    }
    const entry = list.bases.find((base) => slug(base.baseType) === name);
    if (!entry) return undefined;
    const [band, linkPart, qualityPart] = parts;
    const [min, max] = (band ?? "").split("-").map(Number);
    if (!min || !max) return undefined;
    const quality = qualityPart === "q25" ? 25 : qualityPart === "q30" ? 30 : null;
    const links =
        linkPart === "6-link" ? "6" : linkPart === "1-5-link" ? "1-5" : entry.links ? "1-5" : null;
    return {
        baseType: entry.baseType,
        category: entry.category,
        value: marketBaseValue(quality ? QUALITY_BAND : { min, max }, links, quality),
    };
}
